define([],function(){const init=()=>{const sliders=document.querySelectorAll('.path-mod-personalityfinder .personalityfinder-stepped-range');const cssEscape=(value)=>{if(window.CSS && typeof window.CSS.escape==='function'){return window.CSS.escape(value);}return value.replace(/(["\\\[\]#.:])/g,'\\$1');};sliders.forEach((slider)=>{const targetName=slider.getAttribute('data-target');if(!targetName){return;}const form=slider.closest('form');if(!form){return;}const hidden=form.querySelector('input[type="hidden"][name="'+cssEscape(targetName)+'"]');if(!hidden){return;}const sync=()=>{hidden.value=slider.value;slider.classList.add('is-selected');};if(hidden.value){slider.value=hidden.value;slider.classList.add('is-selected');}slider.addEventListener('input',sync);slider.addEventListener('change',sync);slider.addEventListener('click',sync);slider.addEventListener('pointerup',sync);slider.addEventListener('keyup',sync);if(!form.dataset.personalityfinderSliderSubmitBound){form.dataset.personalityfinderSliderSubmitBound='1';form.addEventListener('submit',()=>{form.querySelectorAll('.personalityfinder-stepped-range.is-selected').forEach((selectedSlider)=>{const selectedTarget=selectedSlider.getAttribute('data-target');if(!selectedTarget){return;}const selectedHidden=form.querySelector('input[type="hidden"][name="'+cssEscape(selectedTarget)+'"]');if(selectedHidden){selectedHidden.value=selectedSlider.value;}});});}});};return{init:init};});